import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"Agent scheduled tasks","description":"","frontmatter":{"title":"Agent scheduled tasks"},"headers":[],"relativePath":"guide/schedules.md","filePath":"guide/schedules.md"}'),r={name:"guide/schedules.md"};function o(d,e,i,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="agent-scheduled-tasks" tabindex="-1">Agent scheduled tasks <a class="header-anchor" href="#agent-scheduled-tasks" aria-label="Permalink to &quot;Agent scheduled tasks&quot;">​</a></h1><p>An agent schedule submits a task prompt to a chosen agent on a plan. It is not a workflow Crontab trigger.</p><h2 id="create-a-task" tabindex="-1">Create a task <a class="header-anchor" href="#create-a-task" aria-label="Permalink to &quot;Create a task&quot;">​</a></h2><ol><li>Open <strong>Scheduled tasks</strong> in the agent workspace and select <strong>Create task</strong>.</li><li>Choose an agent, then enter a name, optional group/description and an explicit task prompt.</li><li>Choose once, fixed interval, daily, weekly or monthly.</li><li>Complete the displayed time, interval or weekday/date fields and check the next execution time.</li><li>Save and verify that the task is enabled.</li></ol><p>The interface and runtime determine exact time, timezone and execution-window behavior. Do not assume missed work runs after a shutdown.</p><h2 id="run-now-and-inspect-records" tabindex="-1">Run now and inspect records <a class="header-anchor" href="#run-now-and-inspect-records" aria-label="Permalink to &quot;Run now and inspect records&quot;">​</a></h2><ul><li><strong>Run now</strong> verifies the task; it does not prove that its recurring schedule works.</li><li><strong>Enable / pause</strong> controls future runs. A finished task has different behavior from an ordinary enabled one.</li><li><strong>Run records</strong> show status, time and errors. Open the latest associated session when the task provides it.</li><li>Groups, search and status filters affect only the management view.</li></ul><h2 id="agent-schedules-versus-crontab" tabindex="-1">Agent schedules versus Crontab <a class="header-anchor" href="#agent-schedules-versus-crontab" aria-label="Permalink to &quot;Agent schedules versus Crontab&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Execution target</th><th>Results</th></tr></thead><tbody><tr><td>Agent schedule</td><td>Dynamic model reasoning with authorized tools</td><td>Schedule runs and associated agent sessions</td></tr><tr><td><a href="./../trigger_crontab.html">Workflow Crontab</a></td><td>An arranged node-based process</td><td>Workflow execution records</td></tr></tbody></table><h2 id="before-unattended-execution" tabindex="-1">Before unattended execution <a class="header-anchor" href="#before-unattended-execution" aria-label="Permalink to &quot;Before unattended execution&quot;">​</a></h2><p>Run manually and verify the result first. Grant only necessary tools, restrict directories and external services, and define clear task boundaries. Scheduled tasks can incur model charges or modify data. Pause the task before investigating unexpected behavior.</p>',11)])])}const p=t(r,[["render",o]]);export{g as __pageData,p as default};
